import React from 'react';
import { Heart } from 'lucide-react'; // Importing Heart icon from lucide-react

const listings = [
  { id: 1, title: 'iPhone 12 Pro Max', price: 'EGP 15,000', location: 'Cairo', added: '2 days ago', condition: 'New', year: '2024', image: 'https://cdn.mos.cms.futurecdn.net/kSUXaLsWD6dMQuXrSRYMKg.jpg' },
  { id: 2, title: '2 Bedroom Apartment for Rent', price: 'EGP 8,000/month', location: 'Alexandria', added: '5 days ago', condition: 'New', year: '2023', image: '/placeholder.svg?height=200&width=300' },
  { id: 3, title: 'Toyota Corolla 2019', price: 'EGP 250,000', location: 'Giza', added: '1 week ago', condition: 'Used', year: '2019', image: '/placeholder.svg?height=200&width=300' },
  { id: 4, title: 'Leather Sofa Set', price: 'EGP 5,000', location: 'Hurghada', added: '3 days ago', condition: 'New', year: '2023', image: '/placeholder.svg?height=200&width=300' },
];

export default function FeaturedListings({ searchQuery }) {
  const filteredListings = listings.filter((listing) =>
    searchQuery ? listing.title.toLowerCase().includes(searchQuery.toLowerCase()) : true
  );

  return (
    <section className="container mx-auto px-4 py-8">
      <h2 className="text-xl md:text-2xl font-bold mb-6">Featured Listings</h2>
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {filteredListings.map((listing) => (
          <div
            key={listing.id}
            className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow relative"
          >
            <img
              src={listing.image}
              alt={listing.title}
              width={300}
              height={200}
              className="w-full h-56 object-cover"
            />
            <div className="p-4">
              <h3 className="font-semibold mb-1 text-sm md:text-base truncate">{listing.title}</h3>
              <p className="text-red-600 font-bold text-lg">{listing.price}</p>
              <div className="text-gray-600 text-xs md:text-sm mt-2">
                <span className="bg-gray-200 rounded-full px-2 py-1 text-gray-700 mr-2">
                  {listing.condition}
                </span>
                <span>{listing.year}</span>
              </div>
              <p className="text-gray-500 text-xs mt-1">
                {listing.location} · {listing.added}
              </p>
            </div>
            {/* Heart Icon for Favorites */}
            <button className="absolute top-2 right-2 text-gray-500 hover:text-red-500">
              <Heart size={24} />
            </button>
          </div>
        ))}
      </div>
    </section>
  );
}
